+++ b/src/booking.ts
@@ -1,12 +1,29 @@
 import { db } from './db'
 import { payments } from './payments'

 export async function cancelBooking(id: string, reason: string) {
   const booking = await db.bookings.byId(id)
+
+  if (booking.prepaid) {
+    await payments.refund(booking.paymentId, booking.amount)
+  }
+
   await db.bookings.update(id, { status: 'cancelled', reason })
+
+  return { id, refunded: booking.prepaid }
 }
